import { createClient } from '@supabase/supabase-js';

const KEY='so-tai-chinh-viet-v1', CATS=['Ăn uống','Mua sắm','Đội xe','Lương','Hóa đơn','Khác'];
const seed={transactions:[{id:'t1',amount:12500000,type:'income',category:'Lương',date:'2026-08-05T08:00',note:'Lương tháng 8'},{id:'t2',amount:85000,type:'expense',category:'Ăn uống',date:'2026-08-08T08:30',note:'Cà phê sáng'},{id:'t3',amount:1200000,type:'expense',category:'Mua sắm',date:'2026-08-07T17:00',note:'Đồ dùng gia đình'},{id:'t4',amount:450000,type:'expense',category:'Đội xe',date:'2026-08-04T09:00',note:'Đổ xăng và gửi xe'}],orders:[{id:'o1',customer:'Công ty Minh Anh',cost:3500000,sell:6200000,date:'2026-08-09T10:00',paid:6200000,supplierPaid:3500000},{id:'o2',customer:'Nguyễn Hoàng Nam',cost:1800000,sell:3200000,date:'2026-08-07T14:00',paid:1000000,supplierPaid:0},{id:'o3',customer:'Shop Mộc Nhiên',cost:4200000,sell:7600000,date:'2026-08-02T11:00',paid:0,supplierPaid:0}],notes:[{id:'n1',title:'Ý tưởng kinh doanh',body:'Tìm thêm nguồn hàng decor bàn làm việc, ưu tiên sản phẩm thân thiện môi trường.',date:'2026-08-08T09:00'},{id:'n2',title:'Nhắc nhở',body:'Kiểm tra lại các khoản chi định kỳ vào ngày 15 hàng tháng.',date:'2026-08-05T09:00'}],businessBalance:0,balanceMoves:[]};
let state=JSON.parse(localStorage.getItem(KEY)||JSON.stringify(seed));state.businessBalance=+state.businessBalance||0;state.balanceMoves=state.balanceMoves||[];state.profile=state.profile||{name:'Tuấn Anh',email:'',phone:''};state.theme=state.theme||'light';document.documentElement.dataset.theme=state.theme;let view='personal',rangeType='month',customStart='',customEnd='';
const money=n=>new Intl.NumberFormat('vi-VN').format(+n||0),fmt=n=>`${money(n)} ₫`,parseMoney=v=>+String(v||'').replace(/\D/g,'')||0,esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c])),nowLocal=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)},dt=s=>new Date(String(s).includes('T')?s:`${s}T00:00`),dtf=s=>dt(s).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}),save=()=>{pruneData();localStorage.setItem(KEY,JSON.stringify(state));};
function inRange(s){const d=dt(s),n=new Date();if(rangeType==='all')return true;if(rangeType==='custom')return(!customStart||d>=dt(`${customStart}T00:00`))&&(!customEnd||d<=dt(`${customEnd}T23:59`));if(rangeType==='day')return d.toDateString()===n.toDateString();const st=new Date(n);st.setHours(0,0,0,0);st.setDate(n.getDate()-(rangeType==='week'?6:rangeType==='month'?30:365));return d>=st}
function filters(){return `<div class="filters">${[['day','Hôm nay'],['week','Tuần này'],['month','Tháng này'],['year','Năm nay'],['all','Tất cả'],['custom','Tùy chỉnh']].map(x=>`<button class="filter ${rangeType===x[0]?'active':''}" data-range="${x[0]}">${x[1]}</button>`).join('')}</div>${rangeType==='custom'?`<div class="custom-range"><input type="date" id="start-date" value="${customStart}"><span>đến</span><input type="date" id="end-date" value="${customEnd}"></div>`:''}`}
function period(){return rangeType==='day'?'hôm nay':rangeType==='week'?'tuần này':rangeType==='year'?'năm nay':rangeType==='all'?'tất cả':'tháng này'}
function layout(){document.querySelector('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><span class="brand-mark">↗</span>Sổ Tài Chính</div><div class="nav-label">KHÔNG GIAN LÀM VIỆC</div><button class="nav-btn ${view==='personal'?'active':''}" data-view="personal">◈　Quản lí chi tiêu</button><button class="nav-btn ${view==='business'?'active':''}" data-view="business">▣　Kinh doanh</button><button class="nav-btn ${view==='notes'?'active':''}" data-view="notes">▤　Ghi chú</button><div class="sidebar-bottom"><div class="sync"><span class="dot"></span>Đồng bộ tức thì</div><div style="margin-top:8px">Dữ liệu được lưu an toàn trên thiết bị</div></div></aside><main class="main"><header class="topbar"><div class="top-title">${view==='personal'?'Quản lí chi tiêu':view==='business'?'Kinh doanh':'Ghi chú'}</div><div class="top-right"><button class="top-icon" id="theme-toggle" title="Đổi giao diện">${state.theme==='dark'?'☀':'☾'}</button><button class="top-icon" id="profile-edit" title="Chỉnh sửa thông tin">⚙</button><div class="avatar">${esc((state.profile.name||'TA').slice(0,2).toUpperCase())}</div></div></header><section class="content">${view==='personal'?personal():view==='business'?business():notes()}<div class="footer-credit">Hệ thống được phát triển bởi Nguyễn Linh</div></section><nav class="bottom-nav"><button data-view="personal">◈<br>Chi tiêu</button><button data-view="business">▣<br>Kinh doanh</button><button data-view="notes">▤<br>Ghi chú</button></nav></main></div>`;bind()}
function personal(){const a=state.transactions.filter(x=>inRange(x.date)),inc=a.filter(x=>x.type==='income').reduce((s,x)=>s+x.amount,0),out=a.filter(x=>x.type==='expense').reduce((s,x)=>s+x.amount,0),bal=state.transactions.reduce((s,x)=>s+(x.type==='income'?x.amount:-x.amount),0);return `<div class="view-head"><div><div class="eyebrow">TỔNG QUAN TÀI CHÍNH</div><h1>Xin chào, Tuấn Anh 👋</h1><p>Theo dõi dòng tiền của bạn một cách dễ dàng.</p></div><div class="view-actions">${filters()}<button class="btn btn-primary" id="add-tx">＋ Giao dịch mới</button></div></div><div class="cards"><div class="card stat-card"><div class="stat-top">Số dư hiện tại</div><h2>${fmt(bal)}</h2><small>Khả dụng để chi tiêu</small></div><div class="card stat-card"><div class="stat-top">Tổng thu</div><h2 class="income">${fmt(inc)}</h2><small>Trong ${period()}</small></div><div class="card stat-card"><div class="stat-top">Tổng chi</div><h2 class="red">${fmt(out)}</h2><small>Trong ${period()}</small></div><div class="card stat-card"><div class="stat-top">Tỉ lệ tiết kiệm</div><h2>${inc?Math.round((inc-out)/inc*100):0}%</h2><small>So với tổng thu</small></div></div><div class="grid-2"><div class="card"><div class="card-head"><h3>Dòng tiền</h3><span class="muted">6 ngày gần nhất</span></div>${chart(a)}<div class="legend"><span class="income">Thu nhập</span><span class="expense">Chi tiêu</span></div></div><div class="card"><div class="card-head"><h3>Chi tiêu theo danh mục</h3><span class="muted">${period()}</span></div><div class="donut-wrap"><div class="donut"></div><div class="category-legend">${CATS.map(c=>{const v=a.filter(x=>x.type==='expense'&&x.category===c).reduce((s,x)=>s+x.amount,0);return v?`<div class="cat-row"><span class="cat-name">● ${c}</span><b>${Math.round(v/(out||1)*100)}%</b></div>`:''}).join('')||'<span class="muted">Chưa có dữ liệu</span>'}</div></div></div></div><div class="card table-card"><div class="card-head"><h3>Nhật ký giao dịch</h3><div style="display:flex;gap:7px"><input class="search" id="tx-search" placeholder="⌕ Tìm giao dịch..."><select class="search" id="tx-cat"><option>Tất cả</option>${CATS.map(c=>`<option>${c}</option>`).join('')}</select></div></div><div id="tx-list">${transactionList(a.sort((x,y)=>y.date.localeCompare(x.date)))}</div></div>`}
function chart(data){const ds=[...Array(6)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-5+i);return d.toISOString().slice(0,10)}),max=Math.max(1,...ds.flatMap(day=>[...data.filter(x=>x.date.slice(0,10)===day&&x.type==='income').map(x=>x.amount),...data.filter(x=>x.date.slice(0,10)===day&&x.type==='expense').map(x=>x.amount)]));return `<div class="chart">${ds.map(day=>{const i=data.filter(x=>x.date.slice(0,10)===day&&x.type==='income').reduce((s,x)=>s+x.amount,0),o=data.filter(x=>x.date.slice(0,10)===day&&x.type==='expense').reduce((s,x)=>s+x.amount,0);return `<div class="bar-group"><div class="bar in" style="height:${Math.max(4,i/max*85)}%"></div><div class="bar out" style="height:${Math.max(4,o/max*85)}%"></div><span class="bar-label">${new Date(day).toLocaleDateString('vi-VN',{weekday:'short'}).replace('Thứ ','T')}</span></div>`}).join('')}</div>`}
function transactionList(items){if(!items.length)return'<div class="empty">Chưa có giao dịch nào.</div>';const bal=state.transactions.reduce((s,x)=>s+(x.type==='income'?x.amount:-x.amount),0);return items.map(x=>`<div class="transaction"><div class="tx-icon ${x.type==='income'?'income':''}">${x.type==='income'?'↓':'↑'}</div><div class="tx-main"><strong>${esc(x.category)}</strong><div>${esc(x.note||'Không có ghi chú')} · ${dtf(x.date)}</div><div class="balance-move ${x.type}">${x.type==='income'?'Số dư tăng':'Số dư giảm'} ${fmt(x.amount)} · Còn lại ${fmt(bal)}</div></div><div class="amount ${x.type}">${x.type==='income'?'+':'-'} ${fmt(x.amount)}</div><button class="more edit-tx" data-id="${x.id}">✎</button></div>`).join('')}
function business(){const a=state.orders.filter(x=>inRange(x.date)),rev=a.reduce((s,x)=>s+x.sell,0),profit=a.reduce((s,x)=>s+x.sell-x.cost,0),rec=a.reduce((s,x)=>s+Math.max(0,x.sell-(x.customerPaid??x.paid??0)),0),pay=a.reduce((s,x)=>s+Math.max(0,x.cost-(x.supplierPaid||0)),0);return `<div class="view-head"><div><div class="eyebrow">KHÔNG GIAN KINH DOANH</div><h1>Dòng tiền kinh doanh</h1><p>Quản lý vốn, đơn hàng và công nợ rõ ràng.</p></div><div class="view-actions">${filters()}<button class="btn btn-primary" id="add-order">＋ Thêm đơn hàng</button><button class="btn btn-soft" id="add-balance">↕ Cập nhật số dư</button></div></div><div class="business-grid"><div class="card stat-card"><div class="stat-top">Số dư</div><h2>${fmt(state.businessBalance)}</h2><small>Vốn đang sẵn sàng</small></div><div class="card stat-card"><div class="stat-top">Lợi nhuận</div><h2 class="income">${fmt(profit)}</h2><small>Doanh thu − Giá vốn</small></div><div class="card stat-card"><div class="stat-top">Công nợ phải thu</div><h2 class="amber">${fmt(rec)}</h2><small>Khách hàng</small></div><div class="card stat-card"><div class="stat-top">Công nợ phải trả</div><h2 class="red">${fmt(pay)}</h2><small>Nhà cung cấp</small></div><div class="card stat-card"><div class="stat-top">Tổng doanh thu</div><h2>${fmt(rev)}</h2><small>${a.length} đơn trong bộ lọc</small></div></div><div class="grid-2"><div class="card"><div class="card-head"><h3>Biến động số dư</h3><span class="muted">Nạp/rút vốn</span></div>${moves()}<div class="card-head" style="margin-top:20px"><h3>Doanh thu & Chi phí</h3></div>${chart(a.flatMap(x=>[{date:x.date,type:'income',amount:x.sell},{date:x.date,type:'expense',amount:x.cost}]))}</div><div class="card"><div class="card-head"><h3>Đơn hàng gần đây</h3><span class="muted">${a.length} đơn</span></div>${orders(a.slice().sort((x,y)=>y.date.localeCompare(x.date)).slice(0,3))}</div></div><div class="card table-card"><div class="card-head"><h3>Quản lý đơn hàng</h3><input class="search" id="order-search" placeholder="⌕ Tìm khách hàng..."></div><div id="orders-list">${orders(a)}</div></div>`}
function moves(){return state.balanceMoves.length?state.balanceMoves.map(x=>`<div class="transaction"><div class="tx-icon ${x.amount>0?'income':''}">${x.amount>0?'↓':'↑'}</div><div class="tx-main"><strong>${x.amount>0?'Nạp vốn kinh doanh':'Rút vốn kinh doanh'}</strong><div>${esc(x.note||'Không có ghi chú')} · ${dtf(x.date)}</div></div><div class="amount ${x.amount>0?'income':'expense'}">${x.amount>0?'+':'-'} ${fmt(Math.abs(x.amount))}</div></div>`).join(''):'<div class="empty">Chưa có biến động số dư.</div>'}
function orders(items){return items.length?items.map(x=>{const cp=x.customerPaid??x.paid??0,sp=x.supplierPaid||0,debt=Math.max(0,x.sell-cp),sd=Math.max(0,x.cost-sp),p=x.sell-x.cost;return `<div class="order-card"><div class="order-top"><strong>${esc(x.customer)}</strong><span class="badge ${debt?'badge-debt':'badge-paid'}">${debt?'Khách còn nợ '+fmt(debt):'Đã thu đủ'}</span></div><div class="order-meta"><span>${dtf(x.date)}</span><span>Giá nhập: ${fmt(x.cost)}</span></div><div class="order-values"><div>Giá bán<strong>${fmt(x.sell)}</strong></div><div>Lợi nhuận<strong class="income">${fmt(p)}</strong></div><div>Tỷ suất<strong>${x.cost?Math.round(p/x.cost*100):0}%</strong></div></div><div class="order-deposits">NCC đã cọc: <b>${fmt(x.supplierDeposit||0)}</b>　·　Khách đã cọc: <b>${fmt(x.customerDeposit||0)}</b></div><div class="order-deposits">Đã trả NCC: <b>${fmt(sp)}</b>　·　Còn trả: <b class="red">${fmt(sd)}</b></div><div class="order-actions"><button class="btn btn-soft update-order" data-id="${x.id}">Cập nhật thanh toán</button><button class="icon-btn edit-order" data-id="${x.id}">✎ Sửa đơn hàng</button></div></div>`}).join(''):'<div class="empty">Chưa có đơn hàng nào.</div>'}
function notes(){const a=state.notes.filter(x=>inRange(x.date));return `<div class="view-head"><div><div class="eyebrow">GHI CHÚ CÁ NHÂN</div><h1>Không gian ghi chú</h1><p>Lưu lại những ý tưởng và việc quan trọng trong ngày.</p></div><div class="view-actions">${filters()}<button class="btn btn-primary" id="add-note">＋ Ghi chú mới</button></div></div><div class="notes-grid">${a.map((n,i)=>`<div class="card note note-color-${i%5}"><span class="note-pin">★</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>Cập nhật ${dtf(n.date)} · <button class="btn-ghost edit-note" data-id="${n.id}">Chỉnh sửa</button></small></div>`).join('')||'<div class="empty">Chưa có ghi chú nào.</div>'}</div>`}
function bind(){document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>{view=x.dataset.view;layout()});document.querySelectorAll('[data-range]').forEach(x=>x.onclick=()=>{rangeType=x.dataset.range;layout()});document.querySelector('#start-date')?.addEventListener('change',e=>{customStart=e.target.value;layout()});document.querySelector('#end-date')?.addEventListener('change',e=>{customEnd=e.target.value;layout()});document.querySelector('#add-tx')?.addEventListener('click',()=>openModal('tx'));document.querySelector('#add-order')?.addEventListener('click',()=>openModal('order'));document.querySelector('#add-note')?.addEventListener('click',()=>openModal('note'));document.querySelector('#add-balance')?.addEventListener('click',()=>openModal('balance'));document.querySelectorAll('.edit-tx').forEach(x=>x.onclick=()=>openModal('tx',state.transactions.find(y=>y.id===x.dataset.id)));document.querySelectorAll('.edit-order').forEach(x=>x.onclick=()=>openModal('order',state.orders.find(y=>y.id===x.dataset.id)));document.querySelectorAll('.edit-note').forEach(x=>x.onclick=()=>openModal('note',state.notes.find(y=>y.id===x.dataset.id)));document.querySelectorAll('.update-order').forEach(x=>x.onclick=()=>payOrder(x.dataset.id));const q=document.querySelector('#tx-search'),cat=document.querySelector('#tx-cat');const rt=()=>{const s=(q?.value||'').toLowerCase(),a=state.transactions.filter(x=>inRange(x.date)&&(!s||`${x.category} ${x.note}`.toLowerCase().includes(s))&&(!cat||cat.value==='Tất cả'||x.category===cat.value));const t=document.querySelector('#tx-list');if(t)t.innerHTML=transactionList(a);t?.querySelectorAll('.edit-tx').forEach(x=>x.onclick=()=>openModal('tx',state.transactions.find(y=>y.id===x.dataset.id)))};q?.addEventListener('input',rt);cat?.addEventListener('change',rt);document.querySelector('#order-search')?.addEventListener('input',e=>{const t=document.querySelector('#orders-list');t.innerHTML=orders(state.orders.filter(x=>inRange(x.date)&&x.customer.toLowerCase().includes(e.target.value.toLowerCase())));bind()})}
function payOrder(id){const o=state.orders.find(x=>x.id===id),cp=parseMoney(prompt(`Khách trả thêm (đã thu ${fmt(o.customerPaid??o.paid??0)}):`,'0')),sp=parseMoney(prompt(`Trả thêm nhà cung cấp (đã trả ${fmt(o.supplierPaid||0)}):`,'0'));if(cp)o.customerPaid=Math.min(o.sell,(o.customerPaid??o.paid??0)+cp);if(sp)o.supplierPaid=Math.min(o.cost,(o.supplierPaid||0)+sp);save();layout();toast('Đã cập nhật thanh toán')}
function openModal(type,item={}){const tx=type==='tx',ord=type==='order',bal=type==='balance',title=bal?'Cập nhật số dư':item.id?`Sửa ${tx?'giao dịch':ord?'đơn hàng':'ghi chú'}`:`Thêm ${tx?'giao dịch mới':ord?'đơn hàng mới':'ghi chú mới'}`;const moneyInput=(name,label,val,req='')=>`<div class="field"><label>${label}</label><input class="money-input" name="${name}" type="text" inputmode="numeric" value="${val?money(val):''}" ${req} placeholder="Không bắt buộc"></div>`;let body=tx?`<div class="form-grid">${moneyInput('amount','Số tiền (VNĐ)',item.amount,'required')}<div class="field"><label>Loại</label><select name="txType"><option value="expense" ${item.type!=='income'?'selected':''}>Chi tiêu</option><option value="income" ${item.type==='income'?'selected':''}>Thu nhập</option></select></div><div class="field"><label>Danh mục</label><select name="category">${CATS.map(c=>`<option ${item.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Ngày và giờ</label><input name="date" type="datetime-local" value="${item.date?.slice(0,16)||nowLocal()}" required></div><div class="field full"><label>Ghi chú</label><textarea name="note">${esc(item.note||'')}</textarea></div></div>`:ord?`<div class="form-grid"><div class="field full"><label>Tên khách hàng</label><input name="customer" value="${esc(item.customer||'')}" required></div>${moneyInput('cost','Giá nhập (VNĐ)',item.cost,'required')}${moneyInput('supplierDeposit','Nhà cung cấp đã cọc',item.supplierDeposit)}${moneyInput('sell','Giá bán (VNĐ)',item.sell,'required')}${moneyInput('customerDeposit','Khách hàng đã cọc',item.customerDeposit)}<div class="field"><label>Ngày và giờ lên đơn</label><input name="date" type="datetime-local" value="${item.date?.slice(0,16)||nowLocal()}" required></div><div class="field full order-preview">Lợi nhuận: <b id="profit-preview">${fmt((item.sell||0)-(item.cost||0))}</b>　 Tỷ suất: <b id="margin-preview">${item.cost?Math.round((item.sell-item.cost)/item.cost*100):0}%</b></div></div>`:bal?`<div class="form-grid"><div class="field"><label>Loại cập nhật</label><select name="balanceType"><option value="deposit">Nạp tiền vào vốn</option><option value="withdraw">Rút tiền ra</option></select></div>${moneyInput('amount','Số tiền (VNĐ)',0,'required')}<div class="field full"><label>Ngày và giờ</label><input name="date" type="datetime-local" value="${nowLocal()}" required></div><div class="field full"><label>Ghi chú</label><textarea name="note"></textarea></div></div>`:`<div class="form-grid"><div class="field full"><label>Tiêu đề</label><input name="title" value="${esc(item.title||'')}" required></div><div class="field full"><label>Nội dung</label><textarea name="body" required>${esc(item.body||'')}</textarea></div></div>`;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="close">×</button></div><form id="modal-form" data-type="${type}" data-id="${item.id||''}">${body}<div class="form-actions"><button type="button" class="btn btn-ghost close">Hủy</button><button type="submit" class="btn btn-primary">Lưu lại</button></div></form></div></div>`);document.querySelectorAll('.close').forEach(x=>x.onclick=()=>document.querySelector('.modal-back')?.remove());document.querySelectorAll('.money-input').forEach(x=>x.oninput=()=>x.value=money(parseMoney(x.value)));const f=document.querySelector('#modal-form');f.onsubmit=saveForm;f.querySelectorAll('[name=cost],[name=sell]').forEach(x=>x.oninput=()=>{const c=parseMoney(f.elements.cost?.value),s=parseMoney(f.elements.sell?.value);f.querySelector('#profit-preview').textContent=fmt(s-c);f.querySelector('#margin-preview').textContent=`${c?Math.round((s-c)/c*100):0}%`})}
function saveForm(e){e.preventDefault();const f=new FormData(e.currentTarget),type=e.currentTarget.dataset.type,id=e.currentTarget.dataset.id||`id-${Date.now()}`;if(type==='balance'){const n=parseMoney(f.get('amount'))*(f.get('balanceType')==='withdraw'?-1:1);state.businessBalance+=n;state.balanceMoves.unshift({id,date:f.get('date'),amount:n,note:f.get('note')})}else{let o=type==='tx'?{id,amount:parseMoney(f.get('amount')),type:f.get('txType'),category:f.get('category'),date:f.get('date'),note:f.get('note')}:type==='order'?{id,customer:f.get('customer'),cost:parseMoney(f.get('cost')),sell:parseMoney(f.get('sell')),supplierDeposit:parseMoney(f.get('supplierDeposit')),customerDeposit:parseMoney(f.get('customerDeposit')),customerPaid:state.orders.find(x=>x.id===id)?.customerPaid||parseMoney(f.get('customerDeposit')),supplierPaid:state.orders.find(x=>x.id===id)?.supplierPaid||0,date:f.get('date')}:{id,title:f.get('title'),body:f.get('body'),date:nowLocal()};const a=type==='tx'?state.transactions:type==='order'?state.orders:state.notes,i=a.findIndex(x=>x.id===id);i<0?a.unshift(o):a[i]=o}save();document.querySelector('.modal-back')?.remove();layout();toast('Đã lưu thành công')}
function toast(msg){const old=document.querySelector('.toast');old?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="toast">✓ ${msg}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),2600)}
window.addEventListener('storage',e=>{if(e.key===KEY){state=JSON.parse(e.newValue);layout();toast('Dữ liệu vừa được đồng bộ')}});
const _openModal=openModal,_saveForm=saveForm,_bind=bind;
function askDelete(kind,id){const arr=kind==='giao dịch'?state.transactions:kind==='đơn hàng'?state.orders:state.notes,item=arr.find(x=>x.id===id),label=kind==='giao dịch'?(item?.note||item?.category):kind==='đơn hàng'?(item?.customer):item?.title;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back delete-back"><div class="modal delete-modal"><div class="delete-symbol">!</div><div class="modal-head"><h2>Xoá ${kind}?</h2><button class="close">×</button></div><p class="delete-question">Bạn có chắc muốn xoá <b>${esc(label||kind)}</b> không?</p><p class="delete-warning">Hành động này không thể hoàn tác. Dữ liệu sẽ bị xoá khỏi ứng dụng.</p><div class="form-actions"><button type="button" class="btn btn-ghost close">Huỷ bỏ</button><button type="button" class="btn btn-danger confirm-delete">Xoá vĩnh viễn</button></div></div></div>`);document.querySelectorAll('.delete-back .close').forEach(x=>x.onclick=()=>document.querySelector('.delete-back')?.remove());document.querySelector('.confirm-delete').onclick=()=>{const i=arr.findIndex(x=>x.id===id);if(i>=0)arr.splice(i,1);save();document.querySelector('.delete-back')?.remove();layout();toast('Đã xoá dữ liệu')}}
transactionList=function(items){if(!items.length)return'<div class="empty">Chưa có giao dịch nào.</div>';const bal=state.transactions.reduce((s,x)=>s+(x.type==='income'?x.amount:-x.amount),0);return items.map(x=>`<div class="transaction"><div class="tx-icon ${x.type==='income'?'income':''}">${x.type==='income'?'↓':'↑'}</div><div class="tx-main"><strong>${esc(x.category)}</strong><div>${esc(x.note||'Không có ghi chú')} · ${dtf(x.date)}</div><div class="balance-move ${x.type}">${x.type==='income'?'Số dư tăng':'Số dư giảm'} ${fmt(x.amount)} · Còn lại ${fmt(bal)}</div></div><div class="amount ${x.type}">${x.type==='income'?'+':'-'} ${fmt(x.amount)}</div><button class="more edit-tx" data-id="${x.id}">✎</button><button class="icon-btn delete-tx" data-id="${x.id}" title="Xoá">🗑</button></div>`).join('')};
orders=function(items){if(!items.length)return'<div class="empty">Chưa có đơn hàng nào.</div>';return items.map(x=>{const cp=x.customerPaid??x.paid??0,sp=x.supplierPaid||0,debt=Math.max(0,x.sell-cp),sd=Math.max(0,x.cost-sp),p=x.sell-x.cost;return `<div class="order-card"><div class="order-top"><strong>${esc(x.customer)}</strong><span class="badge ${debt?'badge-debt':'badge-paid'}">${debt?'Khách còn nợ '+fmt(debt):'Đã thu đủ'}</span></div><div class="order-meta"><span>${dtf(x.date)}</span></div><div class="order-values"><div>Giá nhập<strong>${fmt(x.cost)}</strong></div><div>Giá bán<strong>${fmt(x.sell)}</strong></div><div>Lợi nhuận<strong class="income">${fmt(p)}</strong></div></div><div class="order-deposits">Tiền cọc nhà cung cấp: <b>${fmt(x.supplierDeposit||0)}</b></div><div class="order-deposits">Tiền khách đã cọc: <b>${fmt(x.customerDeposit||0)}</b></div><div class="order-deposits">Đã trả nhà cung cấp: <b>${fmt(sp)}</b>　·　Còn trả: <b class="red">${fmt(sd)}</b></div><div class="order-actions"><button class="btn btn-soft update-order" data-id="${x.id}">Cập nhật thanh toán</button><button class="icon-btn edit-order" data-id="${x.id}">✎ Sửa</button><button class="icon-btn delete-order" data-id="${x.id}">🗑 Xoá</button></div></div>`}).join('')};
notes=function(){const a=state.notes.filter(x=>inRange(x.date));return `<div class="view-head"><div><div class="eyebrow">GHI CHÚ CÁ NHÂN</div><h1>Không gian ghi chú</h1><p>Lưu lại những ý tưởng và việc quan trọng trong ngày.</p></div><div class="view-actions">${filters()}<button class="btn btn-primary" id="add-note">＋ Ghi chú mới</button></div></div><div class="notes-grid">${a.map((n,i)=>`<div class="card note note-color-${i%5}"><span class="note-pin">★</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>Cập nhật ${dtf(n.date)} · <button class="btn-ghost edit-note" data-id="${n.id}">Sửa</button> <button class="btn-ghost delete-note" data-id="${n.id}">Xoá</button></small></div>`).join('')||'<div class="empty">Chưa có ghi chú nào.</div>'}</div>`};
openModal=function(type,item={}){if(type==='profile'){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back"><div class="modal"><div class="modal-head"><h2>Chỉnh sửa thông tin</h2><button class="close">×</button></div><form id="profile-form"><div class="form-grid"><div class="field full"><label>Họ và tên</label><input name="name" value="${esc(state.profile.name)}" required></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(state.profile.email)}"></div><div class="field"><label>Số điện thoại</label><input name="phone" value="${esc(state.profile.phone)}"></div></div><div class="form-actions"><button type="button" class="btn btn-ghost close">Hủy</button><button class="btn btn-primary">Lưu thông tin</button></div></form></div></div>`);document.querySelectorAll('.close').forEach(x=>x.onclick=()=>document.querySelector('.modal-back')?.remove());document.querySelector('#profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.profile={name:f.get('name'),email:f.get('email'),phone:f.get('phone')};save();document.querySelector('.modal-back').remove();layout();toast('Đã cập nhật thông tin')};return}if(type==='payment'){const o=item,cp=o.customerPaid??o.paid??0,sp=o.supplierPaid||0;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back"><div class="modal payment-modal"><div class="modal-head"><h2>Cập nhật thanh toán</h2><button class="close">×</button></div><p class="muted">${esc(o.customer)} · ${dtf(o.date)}</p><div class="payment-summary"><div>Khách còn nợ<strong>${fmt(Math.max(0,o.sell-cp))}</strong></div><div>Nhà cung cấp còn phải trả<strong>${fmt(Math.max(0,o.cost-sp))}</strong></div></div><form id="payment-form" data-id="${o.id}"><div class="form-grid"><div class="field"><label>Khách trả thêm</label><input class="money-input" name="customerPay" inputmode="numeric" placeholder="0"></div><div class="field"><label>Trả thêm nhà cung cấp</label><input class="money-input" name="supplierPay" inputmode="numeric" placeholder="0"></div></div><div class="form-actions"><button type="button" class="btn btn-ghost close">Hủy</button><button class="btn btn-primary">Lưu thanh toán</button></div></form></div></div>`);document.querySelectorAll('.close').forEach(x=>x.onclick=()=>document.querySelector('.modal-back')?.remove());document.querySelectorAll('.money-input').forEach(x=>x.oninput=()=>x.value=money(parseMoney(x.value)));document.querySelector('#payment-form').onsubmit=saveForm;return}_openModal(type,item)};
saveForm=function(e){if(e.currentTarget.id==='payment-form'){e.preventDefault();const f=new FormData(e.currentTarget),o=state.orders.find(x=>x.id===e.currentTarget.dataset.id),cp=parseMoney(f.get('customerPay')),sp=parseMoney(f.get('supplierPay'));if(cp){o.customerPaid=Math.min(o.sell,(o.customerPaid??o.paid??0)+cp);state.businessBalance+=cp;state.balanceMoves.unshift({id:`m-${Date.now()}`,date:nowLocal(),amount:cp,note:`Khách ${o.customer} thanh toán`})}if(sp){o.supplierPaid=Math.min(o.cost,(o.supplierPaid||0)+sp);state.businessBalance-=sp;state.balanceMoves.unshift({id:`m-${Date.now()}-s`,date:nowLocal(),amount:-sp,note:`Thanh toán nhà cung cấp cho ${o.customer}`})}save();document.querySelector('.modal-back')?.remove();layout();toast('Đã cập nhật thanh toán và biến động số dư');return}_saveForm(e)};
payOrder=id=>openModal('payment',state.orders.find(x=>x.id===id));
bind=function(){_bind();document.querySelector('#theme-toggle')?.addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;save();layout()});document.querySelector('#profile-edit')?.addEventListener('click',()=>openModal('profile'));document.querySelectorAll('.delete-tx').forEach(x=>x.onclick=()=>askDelete('giao dịch',x.dataset.id));document.querySelectorAll('.delete-order').forEach(x=>x.onclick=()=>askDelete('đơn hàng',x.dataset.id));document.querySelectorAll('.delete-note').forEach(x=>x.onclick=()=>askDelete('ghi chú',x.dataset.id))};
state.history=state.history||[];
function historyPage(){const labels={tx:'Giao dịch',order:'Đơn hàng',balance:'Cập nhật số dư',note:'Ghi chú',payment:'Thanh toán'};return `<div class="view-head"><div><div class="eyebrow">NHẬT KÝ HOẠT ĐỘNG</div><h1>Lịch sử</h1><p>Xem lại các thao tác đã thực hiện trong ứng dụng.</p></div></div><div class="card history-card">${state.history.length?state.history.map((h,i)=>`<div class="history-row"><div class="history-icon ${h.action==='Xoá'?'deleted':''}">${h.action==='Xoá'?'🗑':h.action==='Hoàn tác'?'↶':'✓'}</div><div class="history-main"><strong>${h.action} ${labels[h.type]||''}</strong><div>${esc(h.label||'')} · ${dtf(h.date)}</div></div>${h.action==='Xoá'?`<button class="btn btn-soft undo-history" data-index="${i}">Hoàn tác</button>`:''}</div>`).join(''):'<div class="empty">Chưa có hoạt động nào.</div>'}</div>`}
var baseLayoutV2=layout;baseLayoutV2&& (layout=function(){baseLayoutV2();const nav=document.querySelector('.sidebar .nav-label');if(nav&&!document.querySelector('[data-view="history"]'))nav.insertAdjacentHTML('afterend','<button class="nav-btn history-nav" data-view="history">↺　Lịch sử</button>');if(view==='history'){const c=document.querySelector('.content');c.innerHTML=historyPage()+'<div class="footer-credit">Hệ thống được phát triển bởi Nguyễn Linh</div>';document.querySelector('.top-title').textContent='Lịch sử';document.querySelector('.history-nav')?.classList.add('active');document.querySelectorAll('.undo-history').forEach(x=>x.onclick=()=>undoHistory(+x.dataset.index))}});
function undoHistory(index){const h=state.history[index];if(!h||h.action!=='Xoá')return;const arr=h.type==='tx'?state.transactions:h.type==='order'?state.orders:state.notes;arr.splice(Math.min(h.index,arr.length),0,h.item);state.history.splice(index,1);state.history.unshift({action:'Hoàn tác',type:h.type,label:h.label,date:nowLocal()});save();layout();toast('Đã hoàn tác, dữ liệu trở về vị trí cũ')}
var baseAskDeleteV2=askDelete;askDelete=function(kind,id){const arr=kind==='giao dịch'?state.transactions:kind==='đơn hàng'?state.orders:state.notes,item=arr.find(x=>x.id===id),type=kind==='giao dịch'?'tx':kind==='đơn hàng'?'order':'note';document.body.insertAdjacentHTML('beforeend',`<div class="modal-back delete-back"><div class="modal delete-modal"><div class="delete-symbol">!</div><div class="modal-head"><h2>Xoá ${kind}?</h2><button class="close">×</button></div><p class="delete-question">Bạn có chắc muốn xoá <b>${esc(item?.customer||item?.title||item?.note||kind)}</b> không?</p><p class="delete-warning">Hành động này có thể hoàn tác trong mục Lịch sử.</p><div class="form-actions"><button type="button" class="btn btn-ghost close">Huỷ bỏ</button><button type="button" class="btn btn-danger confirm-delete">Xoá vĩnh viễn</button></div></div></div>`);document.querySelectorAll('.delete-back .close').forEach(x=>x.onclick=()=>document.querySelector('.delete-back')?.remove());document.querySelector('.confirm-delete').onclick=()=>{const index=arr.findIndex(x=>x.id===id),copy=JSON.parse(JSON.stringify(item));arr.splice(index,1);state.history.unshift({action:'Xoá',type,label:item?.customer||item?.title||item?.note||kind,item:copy,index,date:nowLocal()});save();document.querySelector('.delete-back')?.remove();layout();toast('Đã xoá, có thể hoàn tác trong Lịch sử')}};
var baseSaveV2=saveForm;saveForm=function(e){const type=e.currentTarget.dataset.type,id=e.currentTarget.dataset.id,ex=type==='tx'?state.transactions.find(x=>x.id===id):type==='order'?state.orders.find(x=>x.id===id):null;baseSaveV2(e);const names={tx:'Giao dịch',order:'Đơn hàng',balance:'Cập nhật số dư',note:'Ghi chú',payment:'Thanh toán'};if(type){state.history.unshift({action:id?'Cập nhật':'Thêm',type,label:ex?.customer||ex?.note||ex?.title||'',date:nowLocal()});save()}};
var baseBindV2=bind;bind=function(){baseBindV2();document.querySelectorAll('[data-view="history"]').forEach(x=>x.onclick=()=>{view='history';layout()})};
var baseLayoutV3=layout;layout=function(){baseLayoutV3();document.querySelectorAll('[data-view="history"]').forEach(x=>x.onclick=()=>{view='history';layout()});if(view==='history'){document.querySelectorAll('.undo-history').forEach(x=>x.onclick=()=>undoHistory(+x.dataset.index))}if(view==='notes'){document.querySelectorAll('.note').forEach((card,i)=>{if(card.querySelector('.pin-toggle'))return;const note=state.notes.filter(x=>inRange(x.date)).sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||b.date.localeCompare(a.date))[i];card.insertAdjacentHTML('afterbegin',`<button class="pin-toggle ${note?.pinned?'pinned':''}" data-id="${note?.id}">${note?.pinned?'📌':'☆'}</button>`);card.querySelector('.pin-toggle').onclick=()=>{const n=state.notes.find(x=>x.id===note.id);n.pinned=!n.pinned;state.notes.sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||b.date.localeCompare(a.date));save();layout()}})}const h=document.querySelector('.view-head h1');if(h&&view==='personal')h.innerHTML=`Xin chào, ${esc(state.profile.name)} 👋`};
var baseLayoutV4=layout;layout=function(){baseLayoutV4();const side=document.querySelector('.sidebar'),historyNav=side?.querySelector('[data-view="history"]'),bottom=side?.querySelector('.sidebar-bottom');if(historyNav&&bottom)bottom.before(historyNav);const mobile=document.querySelector('.bottom-nav');if(mobile&&!mobile.querySelector('[data-view="history"]'))mobile.insertAdjacentHTML('beforeend','<button data-view="history" class="mobile-history">↺<br>Lịch sử</button>');document.querySelectorAll('[data-view="history"]').forEach(x=>x.onclick=()=>{view='history';layout()});if(view==='history')document.querySelectorAll('[data-view="history"]').forEach(x=>x.classList.add('active'))};
moves=function(){return state.balanceMoves.length?state.balanceMoves.map(x=>{const customer=x.note?.includes('Khách'),supplier=x.note?.includes('nhà cung cấp');const title=customer?'Khách hàng thanh toán':supplier?'Thanh toán nhà cung cấp':x.amount>0?'Nạp vốn kinh doanh':'Rút vốn kinh doanh';return `<div class="transaction"><div class="tx-icon ${x.amount>0?'income':''}">${x.amount>0?'↓':'↑'}</div><div class="tx-main"><strong>${title}</strong><div>${esc(x.note||'Không có ghi chú')} · ${dtf(x.date)}</div><div class="balance-move ${x.amount>0?'income':'expense'}">${x.amount>0?'Số dư tăng':'Số dư giảm'} ${fmt(Math.abs(x.amount))}</div></div><div class="amount ${x.amount>0?'income':'expense'}">${x.amount>0?'+':'-'} ${fmt(Math.abs(x.amount))}</div></div>`}).join(''):'<div class="empty">Chưa có biến động số dư.</div>'};
historyPage=function(){const labels={tx:'Chi tiêu cá nhân',order:'Kinh doanh',balance:'Kinh doanh',note:'Ghi chú',payment:'Kinh doanh'};return `<div class="view-head"><div><div class="eyebrow">NHẬT KÝ HOẠT ĐỘNG</div><h1>Lịch sử</h1><p>Xem lại các thao tác đã thực hiện trong ứng dụng.</p></div></div><div class="card history-card">${state.history.length?state.history.map((h,i)=>{const title=h.type==='order'&&h.action==='Thêm'?'Tạo đơn hàng':`${h.action} ${h.type==='order'?'đơn hàng':h.type==='payment'?'thanh toán':h.type==='balance'?'số dư':h.type==='note'?'ghi chú':'giao dịch'}`;return `<div class="history-row"><div class="history-icon ${h.action==='Xoá'?'deleted':''}">${h.action==='Xoá'?'🗑':h.action==='Hoàn tác'?'↶':'✓'}</div><div class="history-main"><strong>${title}</strong><div>${labels[h.type]||''}${h.label?' · '+esc(h.label):''} · ${dtf(h.date)}</div></div>${h.action==='Xoá'?`<button class="btn btn-soft undo-history" data-index="${i}">Hoàn tác</button>`:''}</div>`}).join(''):'<div class="empty">Chưa có hoạt động nào.</div>'}</div>`};
var baseLayoutV5=layout;layout=function(){baseLayoutV5();if(view==='business'){const grid=document.querySelector('.business-grid');if(grid&&!grid.querySelector('.orders-count-card'))grid.insertAdjacentHTML('beforeend',`<div class="card stat-card orders-count-card"><div class="stat-top">Số lượng đơn hàng</div><h2>${state.orders.filter(x=>inRange(x.date)).length}</h2><small>Trong khoảng thời gian đã chọn</small></div>`);const sub=document.querySelector('.grid-2 .card .card-head .muted');if(sub&&sub.textContent.includes('Nạp/rút'))sub.textContent='Thu/chi theo thanh toán'}};
layout();

// Supabase: tài khoản riêng, lưu cloud và đồng bộ realtime giữa các thiết bị.
const supabase = createClient(import.meta.env.VITE_SUPABASE_URL, import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY);
let cloudUser = null, cloudChannel = null, cloudApplying = false, cloudSaveTimer = null, authMode = 'signin';
const nativeStorageSet = localStorage.setItem.bind(localStorage);
localStorage.setItem = (key, value) => {
  nativeStorageSet(key, value);
  if (key === KEY && cloudUser && !cloudApplying) {
    clearTimeout(cloudSaveTimer);
    cloudSaveTimer = setTimeout(() => saveCloud(JSON.parse(value)), 350);
  }
};
function normaliseState(data) {
  return {...seed, ...data, transactions:data?.transactions||[], orders:data?.orders||[], notes:data?.notes||[], balanceMoves:data?.balanceMoves||[], history:data?.history||[], profile:data?.profile||{name:'Tuấn Anh',email:'',phone:''}, theme:data?.theme||'light'};
}
async function saveCloud(data) {
  if (!cloudUser) return;
  const { error } = await supabase.from('app_states').upsert({user_id: cloudUser.id, data, updated_at: new Date().toISOString()});
  if (error) toast('Không thể đồng bộ: ' + error.message);
}
async function loadCloud() {
  const { data, error } = await supabase.from('app_states').select('data').eq('user_id', cloudUser.id).maybeSingle();
  if (error) { toast('Không thể tải dữ liệu cloud'); return; }
  cloudApplying = true;
  if (data?.data) state = normaliseState(data.data);
  else await supabase.from('app_states').insert({user_id: cloudUser.id, data: state});
  nativeStorageSet(KEY, JSON.stringify(state));
  document.documentElement.dataset.theme = state.theme || 'light';
  cloudApplying = false;
  subscribeCloud();
}
function subscribeCloud() {
  if (cloudChannel) supabase.removeChannel(cloudChannel);
  cloudChannel = supabase.channel('app-state-' + cloudUser.id).on('postgres_changes', {event:'*', schema:'public', table:'app_states', filter:'user_id=eq.' + cloudUser.id}, payload => {
    if (!payload.new?.data) return;
    cloudApplying = true;
    state = normaliseState(payload.new.data);
    nativeStorageSet(KEY, JSON.stringify(state));
    document.documentElement.dataset.theme = state.theme || 'light';
    cloudApplying = false;
    layout();
    toast('Dữ liệu vừa được đồng bộ realtime');
  }).subscribe();
}
function authScreen(message='') {
  document.querySelector('#app').innerHTML = `<main class="auth-shell"><section class="auth-card"><div class="brand"><span class="brand-mark">↗</span>Sổ Tài Chính</div><div class="eyebrow">ĐỒNG BỘ MỌI THIẾT BỊ</div><h1>${authMode==='signin'?'Đăng nhập tài khoản':'Tạo tài khoản mới'}</h1><p>${authMode==='signin'?'Đăng nhập để xem dữ liệu của bạn trên mọi trình duyệt.':'Tạo tài khoản để lưu dữ liệu an toàn trên cloud.'}</p><form id="auth-form"><label>Email<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" required minlength="6" placeholder="Tối thiểu 6 ký tự"></label><button class="btn btn-primary auth-submit">${authMode==='signin'?'Đăng nhập':'Đăng ký'}</button></form><div id="auth-message" class="auth-message">${esc(message)}</div><button class="btn btn-ghost auth-switch">${authMode==='signin'?'Chưa có tài khoản? Đăng ký':'Đã có tài khoản? Đăng nhập'}</button></section></main>`;
  document.querySelector('#auth-form').onsubmit = handleAuth;
  document.querySelector('.auth-switch').onclick = () => { authMode = authMode==='signin'?'signup':'signin'; authScreen(); };
}
async function handleAuth(e) {
  e.preventDefault(); const form = new FormData(e.currentTarget), email=form.get('email'), password=form.get('password');
  const result = authMode==='signin' ? await supabase.auth.signInWithPassword({email,password}) : await supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin}});
  if (result.error) { document.querySelector('#auth-message').textContent=result.error.message; return; }
  if (!result.data.session) { document.querySelector('#auth-message').textContent='Tài khoản đã được tạo. Nếu hệ thống yêu cầu xác nhận email, hãy mở email rồi đăng nhập lại.'; return; }
  cloudUser = result.data.user; await loadCloud(); layout();
}
var cloudBaseLayout = layout;
layout = function() {
  if (!cloudUser) { authScreen(); return; }
  cloudBaseLayout();
  const actions = document.querySelector('.top-right');
  if (actions && !document.querySelector('#cloud-logout')) actions.insertAdjacentHTML('afterbegin', '<button class="top-icon" id="cloud-logout" title="Đăng xuất">⇥</button>');
  document.querySelector('#cloud-logout')?.addEventListener('click', async () => { await supabase.auth.signOut(); cloudUser=null; if(cloudChannel) supabase.removeChannel(cloudChannel); authScreen('Bạn đã đăng xuất.'); });
};
async function bootCloud() {
  const { data:{session} } = await supabase.auth.getSession();
  if (session?.user) { cloudUser=session.user; await loadCloud(); }
  layout();
  supabase.auth.onAuthStateChange(async (event, session) => {
    if (event==='SIGNED_IN' && session?.user && cloudUser?.id !== session.user.id) {
      cloudUser=session.user;
      await loadCloud();
      layout();
    }
    if (event==='SIGNED_OUT') {
      cloudUser=null;
      if (cloudChannel) supabase.removeChannel(cloudChannel);
      authScreen('Bạn đã đăng xuất.');
    }
  });
}
bootCloud();

// Quy tắc dung lượng và trải nghiệm mới: chỉ giữ 30 ghi chú/lịch sử gần nhất.
function pruneData(){
  state.notes=(state.notes||[]).slice().sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||dt(b.date)-dt(a.date)).slice(0,30);
  state.history=(state.history||[]).slice().sort((a,b)=>dt(b.date)-dt(a.date)).slice(0,30);
  state.orders=(state.orders||[]).map(o=>({...o,
    supplierDeposit:+o.supplierDeposit||0,
    customerDeposit:+o.customerDeposit||0,
    supplierPaid:Math.max(+o.supplierPaid||0,+o.supplierDeposit||0),
    customerPaid:Math.max(+o.customerPaid||+o.paid||0,+o.customerDeposit||0)
  }));
}
pruneData();
const cloudNormaliseV2=normaliseState;
normaliseState=function(data){
  const next=cloudNormaliseV2(data);
  state=next; pruneData();
  return state;
};

const incomeCategories=['Lương','Đầu Tư','Kinh Doanh','Thưởng','Khác'];
const expenseCategories=['Ăn Uống','Mua Sắm','Tiền Nhà','Tiền Học','Y Tế','Khác'];
const openModalV2=openModal;
openModal=function(type,item={}){
  openModalV2(type,item);
  if(type!=='tx') return;
  const form=document.querySelector('#modal-form'), select=form?.querySelector('[name=category]'), typeSelect=form?.querySelector('[name=txType]');
  if(!select||!typeSelect) return;
  const refreshCategories=()=>{
    const list=typeSelect.value==='income'?incomeCategories:expenseCategories;
    const selected=select.value||item.category;
    select.innerHTML=list.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${c}</option>`).join('');
    if(selected&&!list.includes(selected)) select.insertAdjacentHTML('beforeend',`<option selected value="${esc(selected)}">${esc(selected)}</option>`);
  };
  refreshCategories(); typeSelect.addEventListener('change',refreshCategories);
};

transactionList=function(items){
  if(!items.length)return'<div class="empty">Chưa có giao dịch nào.</div>';
  let running=state.transactions.reduce((s,x)=>s+(x.type==='income'?x.amount:-x.amount),0);
  return items.map(x=>{const after=running;running-=x.type==='income'?x.amount:-x.amount;return `<div class="transaction"><div class="tx-icon ${x.type==='income'?'income':''}">${x.type==='income'?'↓':'↑'}</div><div class="tx-main"><strong>${esc(x.category)}</strong><div>${esc(x.note||'Không có ghi chú')} · ${dtf(x.date)}</div><div class="balance-move ${x.type}">${x.type==='income'?'Số dư tăng':'Số dư giảm'} ${fmt(x.amount)} · Còn lại ${fmt(after)}</div></div><div class="amount ${x.type}">${x.type==='income'?'+':'-'} ${fmt(x.amount)}</div><button class="more edit-tx" data-id="${x.id}" title="Sửa">✎</button><button class="icon-btn delete-tx" data-id="${x.id}" title="Xoá">🗑</button></div>`}).join('');
};

orders=function(items){
  if(!items.length)return'<div class="empty">Chưa có đơn hàng nào.</div>';
  return items.map(x=>{const cp=Math.max(x.customerPaid??x.paid??0,x.customerDeposit||0),sp=Math.max(x.supplierPaid||0,x.supplierDeposit||0),debt=Math.max(0,x.sell-cp),sd=Math.max(0,x.cost-sp),p=x.sell-x.cost;return `<div class="order-card"><div class="order-top"><strong>${esc(x.customer)}</strong><span class="badge ${debt?'badge-debt':'badge-paid'}">${debt?'Khách còn nợ '+fmt(debt):'Đã thu đủ'}</span></div><div class="order-meta"><span>${dtf(x.date)}</span></div><div class="order-values"><div>Giá nhập<strong>${fmt(x.cost)}</strong></div><div>Giá bán<strong>${fmt(x.sell)}</strong></div><div>Lợi nhuận<strong class="income">${fmt(p)}</strong></div></div><div class="order-deposits supplier-line">Nhà cung cấp · Cọc: <b>${fmt(x.supplierDeposit||0)}</b> · Còn nợ: <b class="red">${fmt(sd)}</b></div><div class="order-deposits customer-line">Khách hàng · Cọc: <b>${fmt(x.customerDeposit||0)}</b> · Còn nợ: <b class="amber">${fmt(debt)}</b></div><div class="order-actions"><button class="btn btn-soft update-order" data-id="${x.id}">Cập nhật thanh toán</button><button class="icon-btn edit-order" data-id="${x.id}">✎ Sửa</button><button class="icon-btn delete-order" data-id="${x.id}">🗑 Xoá</button></div></div>`}).join('');
};

notes=function(){
  const a=state.notes.filter(x=>inRange(x.date)).sort((x,y)=>(y.pinned?1:0)-(x.pinned?1:0)||dt(y.date)-dt(x.date)).slice(0,30);
  return `<div class="view-head"><div><div class="eyebrow">GHI CHÚ CÁ NHÂN</div><h1>Không gian ghi chú</h1><p>Lưu lại những ý tưởng và việc quan trọng trong ngày.</p></div><div class="view-actions">${filters()}<button class="btn btn-primary" id="add-note">＋ Ghi chú mới</button></div></div><div class="notes-grid">${a.map((n,i)=>`<div class="card note note-color-${i%5}"><button class="pin-toggle ${n.pinned?'pinned':''}" data-id="${n.id}">${n.pinned?'📌':'☆'}</button><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>Cập nhật ${dtf(n.date)} · <button class="btn-ghost edit-note" data-id="${n.id}">Sửa</button> <button class="btn-ghost delete-note" data-id="${n.id}">Xoá</button></small></div>`).join('')||'<div class="empty">Chưa có ghi chú nào.</div>'}</div>`;
};

const saveFormV3=saveForm;
saveForm=function(e){
  const type=e.currentTarget.dataset.type,id=e.currentTarget.dataset.id;
  saveFormV3(e);
  if(type==='order'){
    const o=id?state.orders.find(x=>x.id===id):state.orders[0];
    if(o){o.supplierPaid=Math.max(o.supplierPaid||0,o.supplierDeposit||0);o.customerPaid=Math.max(o.customerPaid||0,o.customerDeposit||0);save();layout();}
  }
};

function replaceChartsWithInsights(){
  if(view==='personal'){
    const cards=document.querySelectorAll('.grid-2>.card');
    const a=state.transactions.filter(x=>inRange(x.date)), inc=a.filter(x=>x.type==='income').reduce((s,x)=>s+x.amount,0), out=a.filter(x=>x.type==='expense').reduce((s,x)=>s+x.amount,0);
    const target=cards[0]?.querySelector('.chart');
    if(target) target.outerHTML=`<div class="insight-panel"><div class="insight-main"><span>Chênh lệch kỳ này</span><strong class="${inc-out>=0?'income':'red'}">${fmt(inc-out)}</strong></div><div class="insight-row"><span>Thu nhập</span><b class="income">${fmt(inc)}</b></div><div class="insight-row"><span>Chi tiêu</span><b class="red">${fmt(out)}</b></div><div class="insight-row"><span>Số giao dịch</span><b>${a.length}</b></div></div>`;
    cards[0]?.querySelector('.legend')?.remove();
    const donut=cards[1]?.querySelector('.donut-wrap');
    if(donut){const cats=expenseCategories.map(c=>({c,v:a.filter(x=>x.type==='expense'&&x.category===c).reduce((s,x)=>s+x.amount,0)})).filter(x=>x.v).sort((x,y)=>y.v-x.v).slice(0,5);donut.outerHTML=`<div class="insight-list">${cats.map((x,i)=>`<div class="insight-row"><span><i class="insight-dot dot-${i}"></i>${x.c}</span><b>${fmt(x.v)} · ${Math.round(x.v/(out||1)*100)}%</b></div>`).join('')||'<div class="empty">Chưa có chi tiêu trong kỳ này.</div>'}</div>`;}
  }
  if(view==='business'){
    const card=document.querySelector('.grid-2>.card');
    card?.querySelectorAll('.chart,.legend').forEach(x=>x.remove());
    card?.querySelectorAll('.card-head').forEach(x=>{if(x.querySelector('h3')?.textContent.includes('Doanh thu'))x.remove()});
    if(card&&!card.querySelector('.business-insight')){const a=state.orders.filter(x=>inRange(x.date)),paid=a.reduce((s,x)=>s+Math.min(x.sell,x.customerPaid??x.paid??x.customerDeposit??0),0),supplier=a.reduce((s,x)=>s+Math.min(x.cost,x.supplierPaid??x.supplierDeposit??0),0);card.insertAdjacentHTML('beforeend',`<div class="business-insight"><div class="insight-main"><span>Thực thu trong kỳ</span><strong class="income">${fmt(paid)}</strong></div><div class="insight-row"><span>Đã trả nhà cung cấp</span><b class="red">${fmt(supplier)}</b></div><div class="insight-row"><span>Đơn còn công nợ</span><b>${a.filter(x=>(x.customerPaid??x.paid??x.customerDeposit??0)<x.sell).length}</b></div></div>`)}
  }
}
const layoutV6=layout;
layout=function(){layoutV6();replaceChartsWithInsights();};
if(cloudUser) layout();

function decorateNavigation(){
  const icons={personal:'◉',business:'▣',notes:'✦',history:'◷'};
  const labels={personal:'Quản lí chi tiêu',business:'Kinh doanh',notes:'Ghi chú',history:'Lịch sử'};
  document.querySelectorAll('.sidebar [data-view]').forEach(btn=>{const key=btn.dataset.view;if(!icons[key])return;btn.innerHTML=`<span class="nav-symbol">${icons[key]}</span><span>${labels[key]}</span>`});
  document.querySelectorAll('.bottom-nav [data-view]').forEach(btn=>{const key=btn.dataset.view;if(!icons[key])return;btn.innerHTML=`<span class="nav-symbol">${icons[key]}</span><span>${labels[key]}</span>`});
}
const layoutV7=layout;
layout=function(){layoutV7();decorateNavigation();};
if(cloudUser) layout();
